evaluation_scripts.extractProductList:
() => {
  const cards = document.querySelectorAll('[data-widget="searchResultsV2"] .tile-root');
  const products = [];
  cards.forEach(card => {
    try {
      const link = card.querySelector('a.tile-hover-target')?.href || card.querySelector('a[href*="/product/"]')?.href;
      const title = card.querySelector('span.tsBody500Medium, h3.tsBody500Medium')?.textContent?.trim();
      const priceText = card.querySelector('span.tsHeadline500Medium, span.tsHeadline500Bold')?.textContent?.trim();
      const price = priceText ? parseInt(priceText.replace(/[^\d]/g, '')) : null;
      const oldPriceText = card.querySelector('span.tsBody400Small.tsTextSecondary')?.textContent?.trim();
      const oldPrice = oldPriceText ? parseInt(oldPriceText.replace(/[^\d]/g, '')) : null;
      const ratingText = card.querySelector('span.tsBodyControl400Small, div[class*="rating"]')?.textContent?.trim();
      const rating = ratingText ? parseFloat(ratingText.replace(',', '.')) : null;
      const reviewsText = card.querySelector('span.tsCaption400Small, a[href*="reviews"]')?.textContent?.trim();
      const reviewsCount = reviewsText ? parseInt(reviewsText.replace(/[^\d]/g, '')) : 0;
      const image = card.querySelector('img[class*="image"]')?.src;
      if (link && title) {
        products.push({ link, title, price, oldPrice, rating, reviewsCount, image });
      }
    } catch (e) {}
  });
  return products;
}

evaluation_scripts.extractProductDetails:
() => {
  const result = {};
  try {
    result.title = document.querySelector('h1[data-widget="webProductHeading"]')?.textContent?.trim();
    const priceEl = document.querySelector('span[data-widget="webPrice"] span.tsHeadline500Medium');
    result.price = priceEl ? parseInt(priceEl.textContent?.replace(/[^\d]/g, '')) : null;
    const oldPriceEl = document.querySelector('span[data-widget="webPrice"] span.tsBody400Small');
    result.oldPrice = oldPriceEl ? parseInt(oldPriceEl.textContent?.replace(/[^\d]/g, '')) : null;
    const ratingEl = document.querySelector('div[data-widget="webRating"] span');
    result.rating = ratingEl ? parseFloat(ratingEl.textContent?.replace(',', '.')) : null;
    const reviewsLink = document.querySelector('a[href*="reviews"]');
    result.reviewsCount = reviewsLink ? parseInt(reviewsLink.textContent?.replace(/[^\d]/g, '')) : 0;
    result.reviewsUrl = reviewsLink?.href;

    // Characteristics
    const chars = {};
    const charContainer = document.querySelector('div[data-widget="webCharacteristics"]');
    if (charContainer) {
      charContainer.querySelectorAll('dl, div[class*="characteristic"]').forEach(row => {
        const name = row.querySelector('dt, span[class*="name"]')?.textContent?.trim();
        const value = row.querySelector('dd, span[class*="value"]')?.textContent?.trim();
        if (name && value) chars[name] = value;
      });
    }
    result.characteristics = chars;

    // Availability
    const availText = document.body.innerText;
    if (availText.includes('В наличии')) result.availability = 'В наличии';
    else if (availText.includes('Под заказ')) result.availability = 'Под заказ';
    else if (availText.includes('Нет в наличии')) result.availability = 'Нет в наличии';
    else result.availability = 'Unknown';

    // Seller & Brand
    result.seller = document.querySelector('a[href*="seller"]')?.textContent?.trim();
    result.brand = document.querySelector('a[href*="brand"]')?.textContent?.trim();

    // Article
    const articleMatch = document.body.innerText.match(/Артикул[^\d]*(\d+)/);
    result.article = articleMatch ? articleMatch[1] : null;

    // Images
    result.images = Array.from(document.querySelectorAll('img[data-widget="webGallery"]')).map(img => img.src);
  } catch (e) {}
  return result;
}

evaluation_scripts.extractReviews:
() => {
  const reviews = [];
  try {
    const items = document.querySelectorAll('div[data-widget="webReviews"] > div, div[class*="review-item"]');
    items.forEach(item => {
      try {
        const ratingEl = item.querySelector('div[class*="rating"]');
        const rating = ratingEl ? parseFloat(ratingEl.getAttribute('style')?.match(/width:\s*(\d+)%/) ? parseInt(ratingEl.getAttribute('style').match(/width:\s*(\d+)%/)[1]) / 20 : ratingEl.textContent?.trim()) : null;
        const text = item.querySelector('div[class*="text"], p')?.textContent?.trim();
        const dateEl = item.querySelector('time, span[class*="date"]');
        const date = dateEl ? dateEl.dateTime || dateEl.textContent?.trim() : null;
        if (text) reviews.push({ rating, text, date });
      } catch (e) {}
    });
  } catch (e) {}
  return reviews.slice(0, 5);
}
